type Job<T> = () => Promise<T>;

const MAX_RETRIES = 3;

export class JobQueue {
  private pending: (() => void)[] = [];
  private active = 0;
  private idleResolvers: (() => void)[] = [];

  constructor(private concurrency: number) {}

  /** Queues a job; resolves with its result, or rejects once all retries fail. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        try {
          resolve(await this.attempt(job));
        } catch (err) {
          reject(err);
        } finally {
          this.active--;
          this.next();
        }
      });
      this.next();
    });
  }

  /** Resolves when nothing is running or waiting. */
  onIdle(): Promise<void> {
    if (this.active === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleResolvers.push(resolve));
  }

  private async attempt<T>(job: Job<T>): Promise<T> {
    for (let retries = 0; ; retries++) {
      try {
        return await job();
      } catch (err) {
        if (retries >= MAX_RETRIES) throw err;
      }
    }
  }

  private next(): void {
    while (this.active < this.concurrency && this.pending.length > 0) {
      this.active++;
      this.pending.shift()!();
    }
    if (this.active === 0 && this.pending.length === 0) {
      for (const resolve of this.idleResolvers.splice(0)) resolve();
    }
  }
}
```

A job runs up to four times (one try plus three immediate retries), and `add()` rejects after the last failure, so await or `.catch` each returned promise or Node will report an unhandled rejection. `onIdle()` resolves whether jobs succeeded or failed.
